import pandas as pd
import numpy as np
import warnings
import io
import sys

# Capture warnings to see if any are raised
def capture_warnings_and_run(func):
    """Run a function and capture any warnings raised"""
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = func()
        warning_messages = [str(warning.message) for warning in w]
        return result, warning_messages

# Example 1: Out-of-range float (above int64 max)
def test_1():
    val = float(int(np.iinfo(np.dtype(int)).max) + 1)
    result = pd.Series([val]).convert_dtypes()
    return result

try:
    result, warnings_1 = capture_warnings_and_run(test_1)
    probe("pd.Series([float(int(np.iinfo(np.dtype(int)).max) + 1)]).convert_dtypes()", {
        "dtype": str(result.dtype),
        "value": result[0],
        "warnings": warnings_1
    })
except Exception as e:
    probe("pd.Series([float(int(np.iinfo(np.dtype(int)).max) + 1)]).convert_dtypes()", 
          "__error__: " + type(e).__name__ + ": " + str(e))

